<?php require_once __DIR__.'/_base.php'; $title='Admin Dashboard'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $stats=[];foreach(['users'=>'SELECT COUNT(*) FROM users WHERE role="user"','providers'=>'SELECT COUNT(*) FROM providers','approved'=>'SELECT COUNT(*) FROM providers WHERE verification_status="Approved"','pending'=>'SELECT COUNT(*) FROM providers WHERE verification_status="Pending"','bookings'=>'SELECT COUNT(*) FROM bookings','completed'=>'SELECT COUNT(*) FROM bookings WHERE status="Completed"','value'=>'SELECT COALESCE(SUM(charges),0) FROM bookings','complaints'=>'SELECT COUNT(*) FROM complaints WHERE status="Open"'] as $k=>$sql)$stats[$k]=$pdo->query($sql)->fetchColumn();?><h2>Admin Dashboard</h2><p class="text-secondary">AASRA platform overview.</p><div class="row g-3"><?php foreach([['users','Users'],['providers','Providers'],['approved','Verified Providers'],['pending','Pending Verification'],['bookings','Bookings'],['completed','Completed'],['value','Booking Value'],['complaints','Open Complaints']] as [$k,$l]):?><div class="col-sm-6 col-lg-3"><div class="stat-card"><div class="text-secondary"><?=e($l)?></div><div class="fs-3 fw-bold"><?=in_array($k,['value'])?'PKR '.number_format($stats[$k],0):$stats[$k]?></div></div></div><?php endforeach;?></div><div class="service-card p-4 mt-4"><h4>Quick actions</h4><a class="btn btn-success me-2" href="verification.php">Review Providers</a><a class="btn btn-outline-success me-2" href="bookings.php">Bookings</a><a class="btn btn-outline-success" href="reports.php">Reports</a></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>